'use client'

import * as React from 'react'
import { cva, type VariantProps } from 'class-variance-authority'
import { Xmark } from 'iconoir-react'
import { cn } from '@/lib/utils'
import { Button } from '@/registry/satin/ui/button'
import { useSatinLabels } from '@/registry/satin/ui/labels'
import { bannerMesh, type Mesh } from '@/registry/satin/ui/banner-mesh'

/**
 * Banner, 1:1 with the uiKit `Banner` set (3822:3475): a title, an optional description (one
 * or two lines) and one action, on bg/card with a 1px border/default and the shadcn md shadow.
 *
 * - layout="horizontal": 450 wide, one row, 12 × 8 padding, 10 gap; the action and the close
 *   button sit on the right, 4px apart.
 * - layout="sidebar": 222 wide (the navigation column's inner width), 12 padding, 12 gap; copy on
 *   top, the action stretched across the bottom, close pinned 3px from the top-right corner.
 * - shape="rounded" is radius-xl (12). shape="pill" takes the theme's pill corner on a one-line
 *   horizontal banner (12px at Satin's default corners, fully round at Large) and radius-3xl
 *   (20) wherever the banner is taller.
 * - background="mesh" lays two pre-rendered glows over the card: a light one in Multiply (shows
 *   on white, gone on dark) and a dark one in Screen (glows on dark, gone on white), so it follows
 *   the theme without variables. Figma renders one pair per layout and line count; they are
 *   inlined in banner-mesh.tsx and can be swapped with `mesh`.
 *
 * tone="primary" turns the card action/primary/bg (border action/primary/border) with
 * action/primary/fg copy (description at 80%); its mesh is the dark glow alone, in Screen, so it
 * lightens the primary. `shimmer` sends a soft band of light across now and then.
 *
 * Title is 14/18 medium, description Body/md in text/muted, 2px apart. The close
 * button only renders when `onDismiss` is passed.
 */
const bannerVariants = cva(
  [
    'sa:relative sa:isolate sa:flex sa:max-w-full sa:overflow-clip sa:border sa:border-border-default sa:bg-bg-card',
    'sa:[box-shadow:0_2px_4px_-2px_var(--sa-effect-shadow-sm),0_4px_6px_-1px_var(--sa-effect-shadow-sm)]',
  ],
  {
    variants: {
      layout: {
        horizontal: 'sa:w-[450px] sa:items-center sa:gap-2.5 sa:px-3 sa:py-2',
        sidebar: 'sa:w-[222px] sa:flex-col sa:items-start sa:gap-3 sa:p-3',
      },
      shape: {
        rounded: 'sa:rounded-xl',
        pill: 'sa:rounded-3xl',
      },
      lines: {
        one: '',
        two: '',
      },
    },
    compoundVariants: [{ layout: 'horizontal', shape: 'pill', lines: 'one', className: 'sa:rounded-pill' }],
    defaultVariants: { layout: 'horizontal', shape: 'sa:rounded', lines: 'one' },
  },
)

// The glows are inlined (banner-mesh.tsx), so they come with the component wherever it goes.
export { bannerMesh, type Mesh } from '@/registry/satin/ui/banner-mesh'

export interface BannerProps
  extends Omit<React.ComponentProps<'div'>, 'title'>,
    Omit<VariantProps<typeof bannerVariants>, 'lines'> {
  title: React.ReactNode
  description?: React.ReactNode
  /** One action, usually `<Button variant="secondary">`. Stretches across a sidebar banner. */
  action?: React.ReactNode
  background?: 'mesh' | 'plain'
  /** `primary`: action/primary/bg with action/primary/fg text; its mesh glows lighter on top. */
  tone?: 'default' | 'primary'
  /** Now and then a soft band of light crosses the banner (off under reduced motion). */
  shimmer?: boolean
  /** Shows the close button. */
  onDismiss?: () => void
  /** Accessible name of the close button. Defaults to the `dismiss` label. */
  dismissLabel?: string
  /** Replace the mesh images. */
  mesh?: Mesh
}

export function Banner({
  className,
  title,
  description,
  action,
  layout = 'horizontal',
  background = 'mesh',
  tone = 'default',
  shimmer = false,
  shape = 'rounded',
  onDismiss,
  dismissLabel,
  mesh,
  ...props
}: BannerProps) {
  const labels = useSatinLabels()
  const lines = description ? 'two' : 'one'
  const layoutKey = layout ?? 'horizontal'
  const glow = mesh ?? bannerMesh[layoutKey][lines]
  const sidebar = layoutKey === 'sidebar'
  const primary = tone === 'primary'

  const close = onDismiss && (
    <Button
      variant="tertiary"
      shape="rounded"
      iconOnly
      aria-label={dismissLabel ?? labels.dismiss}
      onClick={onDismiss}
      className={cn(
        sidebar && 'sa:absolute sa:end-[3px] sa:top-[3px] sa:z-10',
        primary && 'sa:text-action-primary-fg sa:[&_svg]:text-action-primary-fg sa:satin-hover:bg-action-primary-bg-hover',
      )}
    >
      <Xmark aria-hidden />
    </Button>
  )

  return (
    <div
      data-slot="banner"
      data-layout={layoutKey}
      data-background={background}
      data-tone={tone}
      className={cn(
        bannerVariants({ layout, shape, lines }),
        primary && 'sa:border-action-primary-border sa:bg-action-primary-bg',
        shimmer && 'satin-sheen',
        className,
      )}
      {...props}
    >
      {background === 'mesh' && primary && (
        <img
          src={glow.dark}
          alt=""
          aria-hidden
          className="sa:pointer-events-none sa:absolute sa:-inset-px sa:-z-10 sa:size-[calc(100%+2px)] sa:max-w-none sa:object-cover sa:mix-blend-screen"
        />
      )}
      {background === 'mesh' && !primary && (
        <>
          <img
            src={glow.light}
            alt=""
            aria-hidden
            className="sa:pointer-events-none sa:absolute sa:-inset-px sa:-z-10 sa:size-[calc(100%+2px)] sa:max-w-none sa:object-cover sa:mix-blend-multiply"
          />
          <img
            src={glow.dark}
            alt=""
            aria-hidden
            className="sa:pointer-events-none sa:absolute sa:-inset-px sa:-z-10 sa:size-[calc(100%+2px)] sa:max-w-none sa:object-cover sa:mix-blend-screen"
          />
        </>
      )}
      <div
        className={cn(
          'sa:flex sa:min-w-0 sa:flex-col sa:justify-center sa:text-sm',
          sidebar ? 'sa:w-full' : 'sa:flex-1',
          description && 'sa:gap-0.5',
        )}
      >
        <p className={cn('sa:truncate sa:text-base sa:leading-[18px] sa:font-medium', primary ? 'sa:text-action-primary-fg' : 'sa:text-text-default')}>{title}</p>
        {description && (
          <p className={cn('sa:text-body', primary ? 'sa:text-action-primary-fg/80' : 'sa:text-text-muted', !sidebar && 'sa:truncate')}>{description}</p>
        )}
      </div>
      {sidebar ? (
        <>
          {action && <div className="sa:flex sa:w-full sa:items-center sa:*:flex-1">{action}</div>}
          {close}
        </>
      ) : (
        (action || close) && (
          <div className="sa:flex sa:shrink-0 sa:items-center sa:gap-1">
            {action}
            {close}
          </div>
        )
      )}
    </div>
  )
}

export { bannerVariants }
